create role authenticated;
create role anon;
create schema auth;
create table auth.users(id uuid primary key);
create function auth.uid() returns uuid language sql stable as $$ select nullif(current_setting('request.jwt.claim.sub',true),'')::uuid $$;
grant usage on schema auth,public to authenticated,anon;
grant execute on function auth.uid() to authenticated,anon;
create table banks(id bigint generated by default as identity primary key,user_id uuid not null references auth.users,name text not null,color text);
create table products(id bigint generated by default as identity primary key,user_id uuid not null references auth.users,bank_id bigint references banks,type text not null,name text not null,total numeric,remaining numeric,installment numeric,total_installments int,start_date date,installment_amount numeric,first_payment_date date);
create table payments(id bigint generated by default as identity primary key,user_id uuid not null references auth.users,product_id bigint references products on delete set null,title text not null,subtitle text,amount numeric default 0,due_date date not null,type text,is_paid boolean default false,is_manual boolean default false);
create table expense_sources(id bigint generated by default as identity primary key,user_id uuid not null references auth.users,title text not null);
alter table banks enable row level security;
alter table products enable row level security;
alter table payments enable row level security;
alter table expense_sources enable row level security;
create policy own_bank on banks for all to authenticated using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy own_product on products for all to authenticated using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy own_payment on payments for all to authenticated using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy own_expense on expense_sources for all to authenticated using(auth.uid()=user_id) with check(auth.uid()=user_id);
grant all on banks,products,payments,expense_sources to authenticated;
grant usage,select on all sequences in schema public to authenticated;
